"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

type WilayaMapHeaderProps = React.ComponentProps<"header"> & {
  title?: React.ReactNode
  description?: React.ReactNode
  actions?: React.ReactNode
}

export function WilayaMapHeader({
  title,
  description,
  actions,
  className,
  children,
  ...props
}: WilayaMapHeaderProps) {
  return (
    <header
      className={cn(
        "relative z-20 flex flex-col gap-3 border-b bg-background px-4 py-3 sm:flex-row sm:items-center sm:justify-between",
        className
      )}
      {...props}
    >
      <div className="min-w-0 space-y-1">
        {title ? <h2 className="font-semibold">{title}</h2> : null}

        {description ? (
          <p className="text-sm text-muted-foreground">{description}</p>
        ) : null}

        {children}
      </div>

      {actions ? (
        <div className="flex shrink-0 items-center gap-2">{actions}</div>
      ) : null}
    </header>
  )
}

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

type WilayaMapLegendItem = {
  label: React.ReactNode
  color: string
}

type WilayaMapLegendProps = React.ComponentProps<"aside"> & {
  items: WilayaMapLegendItem[]
}

export function WilayaMapLegend({
  items,
  className,
  ...props
}: WilayaMapLegendProps) {
  return (
    <aside
      className={cn(
        "absolute bottom-3 left-3 z-10 flex max-w-[calc(100%-1.5rem)] flex-wrap items-center gap-x-4 gap-y-2 rounded-lg border bg-background/90 px-3 py-2 text-xs shadow-sm backdrop-blur",
        className
      )}
      aria-label="Map legend"
      {...props}
    >
      {items.map((item, index) => (
        <div
          key={`${String(item.label)}-${index}`}
          className="flex items-center gap-2"
        >
          <span
            className="size-3 shrink-0 rounded-sm border border-black/10"
            style={{ backgroundColor: item.color }}
            aria-hidden="true"
          />
          <span>{item.label}</span>
        </div>
      ))}
    </aside>
  )
}

"use client"

import { X } from "lucide-react"

import { Badge } from "@/components/ui/badge"

import { useWilayaMapContext } from "@/context/wilaya-map-context"

type WilayaMapSelectionProps = {
  emptyMessage?: string
}

export function WilayaMapSelection({
  emptyMessage = "No wilaya selected",
}: WilayaMapSelectionProps) {
  const { selectedWilayaObjects, removeWilaya } = useWilayaMapContext()

  return (
    <div className="absolute inset-x-0 bottom-0 z-20 border-t bg-background/95 px-4 py-3 backdrop-blur supports-[backdrop-filter]:bg-background/80">
      <div className="flex flex-wrap items-center gap-2">
        {selectedWilayaObjects.length === 0 ? (
          <span className="text-sm text-muted-foreground">
            {emptyMessage}
          </span>
        ) : (
          selectedWilayaObjects.map((wilaya) => (
            <Badge
              key={wilaya.id}
              variant="secondary"
              className="flex items-center gap-2 rounded-full px-3 py-1"
            >
              <span>{wilaya.name}</span>

              <button
                type="button"
                className="rounded-full p-0.5 hover:bg-black/10 dark:hover:bg-white/10"
                onClick={() => removeWilaya(String(wilaya.id))}
                aria-label={`Remove ${wilaya.name}`}
              >
                <X className="size-3" />
              </button>
            </Badge>
          ))
        )}
      </div>
    </div>
  )
}

"use client"

import * as React from "react"
import { Info, Minus, Plus, RotateCcw } from "lucide-react"

import { Button } from "@/components/ui/button"
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip"

import { useWilayaMapContext } from "@/context/wilaya-map-context"

type ToolbarButtonProps = {
  label: string
  onClick: () => void
  children: React.ReactNode
}

function ToolbarButton({
  label,
  onClick,
  children,
}: ToolbarButtonProps) {
  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <Button
          type="button"
          variant="outline"
          size="icon"
          className="h-8 w-8"
          onClick={onClick}
          aria-label={label}
        >
          {children}
        </Button>
      </TooltipTrigger>

      <TooltipContent>{label}</TooltipContent>
    </Tooltip>
  )
}

export function WilayaMapToolbar() {
  const { zoomIn, zoomOut, resetTransform, setIsGuideOpen } =
    useWilayaMapContext()

  return (
    <div className="absolute right-3 top-3 z-10 flex items-center gap-2 rounded-lg border bg-background/90 p-2 shadow-sm backdrop-blur">
      <ToolbarButton label="Zoom out" onClick={zoomOut}>
        <Minus className="size-4" />
      </ToolbarButton>

      <ToolbarButton label="Zoom in" onClick={zoomIn}>
        <Plus className="size-4" />
      </ToolbarButton>

      <ToolbarButton label="Reset map" onClick={resetTransform}>
        <RotateCcw className="size-4" />
      </ToolbarButton>

      <ToolbarButton
        label="Open map guide"
        onClick={() => setIsGuideOpen(true)}
      >
        <Info className="size-4" />
      </ToolbarButton>
    </div>
  )
}

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

import { useWilayaMapContext } from "@/context/wilaya-map-context"
import { BOTTOM_OVERLAY_SPACE } from "@/lib/wilaya-map.utils"

export function WilayaMapViewport({
  className,
  children,
  style,
  ...props
}: React.ComponentProps<"div">) {
  const { mapContainerRef, setIsPointerInside } = useWilayaMapContext()

  return (
    <div
      ref={mapContainerRef}
      className={cn(
        "relative min-h-[420px] w-full overflow-hidden bg-muted/20",
        className
      )}
      style={{
        paddingBottom: BOTTOM_OVERLAY_SPACE,
        ...style,
      }}
      onMouseEnter={() => setIsPointerInside(true)}
      onMouseLeave={() => setIsPointerInside(false)}
      {...props}
    >
      {children}
    </div>
  )
}

import * as React from "react"

import type { AlgeriaWilaya } from "@/lib/algeria-wilayas"
import { useWilayaMap } from "@/hooks/use-wilaya-map"

type WilayaMapContextValue = ReturnType<typeof useWilayaMap> & {
  data: AlgeriaWilaya[]
  selectable: boolean
  strokeColor: string
  selectedColor: string
  height: number
}

const WilayaMapContext = React.createContext<WilayaMapContextValue | null>(null)

export function useWilayaMapContext() {
  const context = React.useContext(WilayaMapContext)

  if (!context) {
    throw new Error(
      "WilayaMap subcomponents must be rendered inside <WilayaMap>."
    )
  }

  return context
}

export const WilayaMapProvider = WilayaMapContext.Provider

import * as React from "react"

import type { AlgeriaWilaya } from "@/lib/algeria-wilayas"

import {
  MAX_SCALE,
  MIN_SCALE,
  PAN_STEP,
  ZOOM_STEP,
  getNextSelectedWilayas,
  getSelectedWilayaObjects,
  getWilayaFillColor,
} from "@/lib/wilaya-map.utils"

type UseWilayaMapParams = {
  data: AlgeriaWilaya[]
  wilayaColors?: Partial<Record<string, string>>
  defaultColor: string
  selectedColor: string
  selectable: boolean

  selectedWilayas?: string[]
  setSelectedWilayas?: React.Dispatch<React.SetStateAction<string[]>>

  onWilayaClick?: (wilaya: AlgeriaWilaya) => void
  onSelectionChange?: (selectedIds: string[]) => void
}

export function useWilayaMap({
  data,
  wilayaColors,
  defaultColor,
  selectedColor,
  selectable,
  selectedWilayas,
  setSelectedWilayas,
  onWilayaClick,
  onSelectionChange,
}: UseWilayaMapParams) {
  const [internalSelected, setInternalSelected] = React.useState<string[]>([])
  const [isPointerInside, setIsPointerInside] = React.useState(false)
  const [isGuideOpen, setIsGuideOpen] = React.useState(false)
  const [transform, setTransform] = React.useState({
    scale: 1,
    x: 0,
    y: 0,
  })

  const mapContainerRef = React.useRef<HTMLDivElement | null>(null)
  const svgRef = React.useRef<SVGSVGElement | null>(null)

  const selected = selectedWilayas ?? internalSelected

  const updateSelection = React.useCallback(
    (next: string[]) => {
      if (setSelectedWilayas) {
        setSelectedWilayas(next)
      } else if (selectedWilayas === undefined) {
        setInternalSelected(next)
      }

      onSelectionChange?.(next)
    },
    [setSelectedWilayas, selectedWilayas, onSelectionChange]
  )

  const toggleWilaya = React.useCallback(
    (wilaya: AlgeriaWilaya, multiSelect: boolean) => {
      const id = String(wilaya.id)

      const next = getNextSelectedWilayas({
        selected,
        wilayaId: id,
        selectable,
        multiSelect,
      })

      if (selectable) {
        updateSelection(next)
      }

      onWilayaClick?.(wilaya)
    },
    [selected, selectable, updateSelection, onWilayaClick]
  )

  const removeWilaya = React.useCallback(
    (id: string) => {
      updateSelection(selected.filter((item) => item !== id))
    },
    [selected, updateSelection]
  )

  const selectedWilayaObjects = React.useMemo(
    () => getSelectedWilayaObjects(data, selected),
    [data, selected]
  )

  const getWilayaFill = React.useCallback(
    (wilayaId: string) =>
      getWilayaFillColor({
        wilayaId,
        selected,
        wilayaColors,
        defaultColor,
        selectedColor,
      }),
    [selected, wilayaColors, defaultColor, selectedColor]
  )

  const getSvgPoint = React.useCallback((clientX: number, clientY: number) => {
    const svg = svgRef.current
    if (!svg) return null

    const point = svg.createSVGPoint()
    point.x = clientX
    point.y = clientY

    const ctm = svg.getScreenCTM()
    if (!ctm) return null

    return point.matrixTransform(ctm.inverse())
  }, [])

  const zoomAtPoint = React.useCallback(
    (clientX: number, clientY: number, nextScale: number) => {
      const svgPoint = getSvgPoint(clientX, clientY)
      if (!svgPoint) return

      setTransform((previous) => {
        const scale = Math.min(
          MAX_SCALE,
          Math.max(MIN_SCALE, nextScale)
        )

        if (scale === previous.scale) {
          return previous
        }

        const worldX = (svgPoint.x - previous.x) / previous.scale
        const worldY = (svgPoint.y - previous.y) / previous.scale

        return {
          scale,
          x: svgPoint.x - worldX * scale,
          y: svgPoint.y - worldY * scale,
        }
      })
    },
    [getSvgPoint]
  )

  const zoomIn = React.useCallback(() => {
    const wrapper = mapContainerRef.current
    if (!wrapper) return

    const rect = wrapper.getBoundingClientRect()

    zoomAtPoint(
      rect.left + rect.width / 2,
      rect.top + rect.height / 2,
      transform.scale + ZOOM_STEP
    )
  }, [transform.scale, zoomAtPoint])

  const zoomOut = React.useCallback(() => {
    const wrapper = mapContainerRef.current
    if (!wrapper) return

    const rect = wrapper.getBoundingClientRect()

    zoomAtPoint(
      rect.left + rect.width / 2,
      rect.top + rect.height / 2,
      transform.scale - ZOOM_STEP
    )
  }, [transform.scale, zoomAtPoint])

  const resetTransform = React.useCallback(() => {
    setTransform({ scale: 1, x: 0, y: 0 })
  }, [])

  React.useEffect(() => {
    const wrapper = mapContainerRef.current
    if (!wrapper) return

    const handleWheel = (event: WheelEvent) => {
      if (!isPointerInside) return

      event.preventDefault()
      event.stopPropagation()

      if (event.ctrlKey) {
        const direction = event.deltaY > 0 ? -1 : 1

        zoomAtPoint(
          event.clientX,
          event.clientY,
          transform.scale + direction * ZOOM_STEP
        )

        return
      }

      setTransform((previous) => {
        const horizontalDelta = event.shiftKey
          ? event.deltaY || event.deltaX
          : event.deltaX

        return {
          ...previous,
          x: previous.x - horizontalDelta * PAN_STEP,
          y: event.shiftKey
            ? previous.y
            : previous.y - event.deltaY * PAN_STEP,
        }
      })
    }

    wrapper.addEventListener("wheel", handleWheel, { passive: false })

    return () => {
      wrapper.removeEventListener("wheel", handleWheel)
    }
  }, [isPointerInside, transform.scale, zoomAtPoint])

  return {
    mapContainerRef,
    svgRef,
    selected,
    transform,
    isGuideOpen,
    setIsGuideOpen,
    setIsPointerInside,
    selectedWilayaObjects,
    getWilayaFill,
    toggleWilaya,
    removeWilaya,
    zoomIn,
    zoomOut,
    resetTransform,
  }
}

import type { AlgeriaWilaya } from "@/lib/algeria-wilayas"

export const MIN_SCALE = 1
export const MAX_SCALE = 6
export const ZOOM_STEP = 0.5
export const PAN_STEP = 1
export const BOTTOM_OVERLAY_SPACE = 116

export function getWilayaFillColor({
  wilayaId,
  selected,
  wilayaColors,
  defaultColor,
  selectedColor,
}: {
  wilayaId: string
  selected: string[]
  wilayaColors?: Partial<Record<string, string>>
  defaultColor: string
  selectedColor: string
}) {
  const color = wilayaColors?.[wilayaId] ?? defaultColor

  if (!selected.includes(wilayaId)) {
    return color
  }

  return selectedColor
}

export function getSelectedWilayaObjects(
  data: AlgeriaWilaya[],
  selected: string[]
) {
  return data.filter((wilaya) => selected.includes(String(wilaya.id)))
}

export function getNextSelectedWilayas({
  selected,
  wilayaId,
  selectable,
  multiSelect,
}: {
  selected: string[]
  wilayaId: string
  selectable: boolean
  multiSelect: boolean
}) {
  if (!selectable) {
    return selected
  }

  if (multiSelect) {
    return selected.includes(wilayaId)
      ? selected.filter((item) => item !== wilayaId)
      : [...selected, wilayaId]
  }

  return selected.length === 1 && selected[0] === wilayaId ? [] : [wilayaId]
}
